require __DIR__ . '/bootstrap.php'; method('POST'); $x=input();$name=trim((string)($x['name']??''));$email=trim((string)($x['email']??''));$message=trim((string)($x['message']??''));if(!$name||!$email||!$message)respond(422,['error'=>'Please complete all required fields.']);if(!filter_var($email,FILTER_VALIDATE_EMAIL))respond(422,['error'=>'Enter a valid email address.']);try{$q=db()->prepare('INSERT INTO soft_ride_messages(name,email,subject,message) VALUES(?,?,?,?)');$q->execute([$name,$email,trim((string)($x['subject']??'')),$message]);respond(201,['ok'=>true]);}catch(Throwable $e){error_log($e);respond(500,['error'=>'Message could not be saved. Please try again.']);}
